<?php $purchasingSection='invoices';require dirname(__DIR__,2).'/components/admin/purchasing-nav.php';$labels=['draft'=>'Borrador','pending'=>'Pendiente','partial'=>'Recepción parcial','received'=>'Recibida','cancelled'=>'Cancelada']; ?>
<section class="admin-page-head"><div><p class="admin-kicker">COMPRAS</p><h1>Facturas de proveedor</h1><p>Registrar el documento no modifica inventario. Solo una recepción física confirmada genera movimientos.</p></div><?php if($capabilities['purchases.create']??false):?><a class="admin-primary-button" href="/admin/purchases/create">+ Nueva factura</a><?php endif?></section>
<form class="admin-panel admin-filter-bar admin-purchase-filter" method="get"><label class="admin-field"><span>Buscar</span><input type="search" name="q" maxlength="120" value="<?= e($q) ?>" placeholder="Proveedor, serie o folio"></label><label class="admin-field"><span>Sucursal</span><select name="branch_id"><?php foreach($branches as$b):?><option value="<?= e($b['id']) ?>" <?= $branchId===(int)$b['id']?'selected':'' ?>><?= e($b['name']) ?></option><?php endforeach?></select></label><label class="admin-field"><span>Estado</span><select name="status"><option value="all">Todos</option><?php foreach($labels as$k=>$v):?><option value="<?= e($k) ?>" <?= $status===$k?'selected':'' ?>><?= e($v) ?></option><?php endforeach?></select></label><label class="admin-field"><span>Desde</span><input type="date" name="from" value="<?= e($from??'') ?>"></label><label class="admin-field"><span>Hasta</span><input type="date" name="until" value="<?= e($until??'') ?>"></label><button class="admin-secondary-button">Aplicar</button></form>
<section class="admin-panel admin-table-panel"><?php if($page->items===[]):?><div class="admin-empty"><strong>Sin facturas registradas</strong><span>No se muestran documentos simulados.</span></div><?php else:?><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Documento</th><th>Proveedor</th><th>Sucursal</th><th>Total</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($page->items as$i):?><tr><td data-label="Documento"><strong><?= e(trim($i['series'].' '.$i['folio'])) ?></strong><small><?= e($i['document_date'].' · '.$i['item_count'].' partidas') ?></small></td><td data-label="Proveedor"><?= e($i['supplier_name']) ?></td><td data-label="Sucursal"><?= e($i['branch_name']) ?></td><td data-label="Total"><?= e('$'.$i['total'].' MXN') ?></td><td data-label="Estado"><span class="admin-status <?= $i['status']==='received'?'is-active':'' ?>"><?= e($labels[$i['status']]??$i['status']) ?></span></td><td class="admin-actions"><a class="admin-secondary-button" href="/admin/purchases/detail?id=<?= e($i['id']) ?>">Detalle</a></td></tr><?php endforeach?></tbody></table></div><?php endif?></section>
